module tb_TopModule;

    logic clk;
    logic aresetn;
    logic x;
    logic z;

    TopModule dut (
        .clk(clk),
        .aresetn(aresetn),
        .x(x),
        .z(z)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Task to apply reset
    task reset_dut();
        begin
            aresetn = 0;
            x = 0;
            #12;
            aresetn = 1;
            #3;
        end
    endtask

    initial begin
        clk = 0;
        aresetn = 0;
        x = 0;

        reset_dut();

        // Test sequence: 1 0 1 0 1 1 0 1
        // Expected z at appropriate cycles
        // Let's drive inputs synchronously on negative edge or just after positive edge
        @(posedge clk);
        x = 1; @(posedge clk); // state S1
        x = 0; @(posedge clk); // state S2
        x = 1; @(posedge clk); // state S1, z should be 1
        x = 0; @(posedge clk); // state S2
        x = 1; @(posedge clk); // state S1, z should be 1
        x = 1; @(posedge clk); // state S1
        x = 0; @(posedge clk); // state S2
        x = 1; @(posedge clk); // state S1, z should be 1
        x = 0; @(posedge clk); // state S2
        x = 0; @(posedge clk); // state S0

        // Check reset behavior mid-stream
        x = 1; @(posedge clk);
        x = 0; @(posedge clk);
        aresetn = 0; @(posedge clk);
        aresetn = 1; @(posedge clk);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

module tb_TopModule;

    logic clk;
    logic aresetn;
    logic x;
    logic z;

    TopModule dut (
        .clk(clk),
        .aresetn(aresetn),
        .x(x),
        .z(z)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Checker task
    task check_seq(input [31:0] seq, input [31:0] expected_z, input int len);
        int i;
        begin
            aresetn = 0;
            #12;
            aresetn = 1;
            @(posedge clk);

            for (i = 0; i < len; i++) begin
                x = seq[len - 1 - i];
                @(posedge clk);
                #1; // wait for propagation
                if (z !== expected_z[len - 1 - i]) begin
                    $display("SELFTEST FAIL: at index %0d, x=%b, expected z=%b, got z=%b", i, x, expected_z[len - 1 - i], z);
                    $finish;
                end
            end
        end
    endtask

    initial begin
        clk = 0;
        aresetn = 0;
        x = 0;

        // Sequence 1: 1, 0, 1, 0, 1
        // Bits: 1 (z=0), 0 (z=0), 1 (z=1), 0 (z=0), 1 (z=1)
        // Expected z: 0, 0, 1, 0, 1
        check_seq(5'b10101, 5'b00101, 5);

        // Sequence 2: 1, 1, 0, 1
        // Bits: 1 (0), 1 (0), 0 (0), 1 (1)
        // Expected z: 0, 0, 0, 1
        check_seq(4'b1101, 4'b0001, 4);

        // Sequence 3: 0, 1, 0, 1, 0
        // Bits: 0 (0), 1 (0), 0 (0), 1 (1), 0 (0)
        // Expected z: 0, 0, 0, 1, 0
        check_seq(5'b01010, 5'b00010, 5);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

