    initial begin
        clk = 0;
        aresetn = 0;
        x = 0;

        // Reset
        #12;
        aresetn = 1;
        @(posedge clk);

        // Apply 1, 0, 1, 0, 1
        // t=0: clk=0
        // Let's step explicitly

        // 1
        x = 1; @(posedge clk); #1; $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);
        // 0
        x = 0; @(posedge clk); #1; $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);
        // 1
        x = 1; @(posedge clk); #1; $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);
        // 0
        x = 0; @(posedge clk); #1; $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);
        // 1
        x = 1; @(posedge clk); #1; $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);

        $finish;
    end

endmodule

module tb_TopModule;

    logic clk;
    logic aresetn;
    logic x;
    logic z;

    TopModule dut (
        .clk(clk),
        .aresetn(aresetn),
        .x(x),
        .z(z)
    );

    // Clock generation
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        aresetn = 0;
        x = 0;

        // Reset
        #12;
        aresetn = 1;
        @(posedge clk);

        // Test sequence: 1, 0, 1, 0, 1
        // 1: state goes S0 -> S1
        x = 1; @(posedge clk); #1; 
        // 0: state goes S1 -> S2
        x = 0; @(posedge clk); #1; 
        // 1: state goes S2 -> S1, z should be 1 *during* S2 when x=1
        // Let's check z before posedge clk:
        x = 1; 
        #3; // wait 3ns into the cycle
        $display("t=%0t x=%b state=%0d z=%b", $time, x, dut.state, z);
        if (z !== 1'b1) begin
            $display("SELFTEST FAIL: expected z=1 for '101'");
            $finish;
        end

        @(posedge clk); #1;
        // 0: state goes S1 -> S2
        x = 0; @(posedge clk); #1; 
        // 1: state goes S2 -> S1, z should be 1
        x = 1; 
        #3;
        if (z !== 1'b1) begin
            $display("SELFTEST FAIL: expected z=1 for second '101'");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
